	}

	private boolean isNearBank(Player player)
	{
		LocalPoint localPoint = player.getLocalLocation();
		if (localPoint == null)
		{
			return false;
		}

		WorldView worldView = client.getTopLevelWorldView();
		Scene scene = worldView.getScene();
		Tile[][][] tiles = scene.getTiles();
		int plane = worldView.getPlane();
		int radius = BANK_RADIUS;

		int playerSceneX = localPoint.getSceneX();
		int playerSceneY = localPoint.getSceneY();

		int minX = Math.max(0, playerSceneX - radius);
		int maxX = Math.min(Constants.SCENE_SIZE - 1, playerSceneX + radius);
		int minY = Math.max(0, playerSceneY - radius);
		int maxY = Math.min(Constants.SCENE_SIZE - 1, playerSceneY + radius);

		for (int x = minX; x <= maxX; x++)
		{
			int dx = x - playerSceneX;
			for (int y = minY; y <= maxY; y++)
			{
				int dy = y - playerSceneY;
				if (Math.max(Math.abs(dx), Math.abs(dy)) > radius)
				{
					continue;
				}

				Tile tile = tiles[plane][x][y];
				if (tile != null && tileHasBankObject(tile))
				{
					return true;
				}
			}
		}

		for (NPC npc : worldView.npcs())
		{
			if (npc == null)
			{
				continue;
			}

			LocalPoint npcLocation = npc.getLocalLocation();
			if (npcLocation == null)
			{
				continue;
			}

			int dx = npcLocation.getSceneX() - playerSceneX;
			int dy = npcLocation.getSceneY() - playerSceneY;
			if (Math.max(Math.abs(dx), Math.abs(dy)) > radius)
			{
				continue;
			}

			if (isBankNpc(npc.getId()))
			{
				return true;
			}
		}

		return false;
	}

	private boolean tileHasBankObject(Tile tile)
	{
		GameObject[] gameObjects = tile.getGameObjects();
		if (gameObjects != null)
		{
			for (GameObject go : gameObjects)
			{
				if (go != null && isBankObject(go.getId()))
				{
					return true;
				}
			}
		}

		WallObject wall = tile.getWallObject();
		if (wall != null && isBankObject(wall.getId()))
		{
			return true;
		}

		DecorativeObject deco = tile.getDecorativeObject();
		if (deco != null && isBankObject(deco.getId()))
		{
			return true;
		}

		GroundObject ground = tile.getGroundObject();
		if (ground != null && isBankObject(ground.getId()))
		{
			return true;
		}

		return false;
	}

	private boolean isBankObject(int id)
	{
		return bankObjectCache.computeIfAbsent(id, this::computeIsBankObject);
	}

	private boolean computeIsBankObject(int id)
	{
		ObjectComposition comp = client.getObjectDefinition(id);
		if (comp == null)
		{
			return false;
		}

		if (comp.getImpostorIds() != null)
		{
			ObjectComposition impostor = comp.getImpostor();
			if (impostor != null)
			{
				comp = impostor;
			}
		}

		String name = comp.getName();
		if (name == null || name.equalsIgnoreCase("null"))
		{
			return false;
		}

		String lower = name.toLowerCase();
		if (!lower.contains("bank"))
		{
			return false;
		}

		String[] actions = comp.getActions();
		if (actions != null)
		{
			for (String action : actions)
			{
				if (action != null && action.equalsIgnoreCase("Bank"))
				{
					return true;
				}
			}
		}

		return lower.contains("bank booth") || lower.contains("bank chest")
			|| lower.contains("bank counter") || lower.contains("bank table");
	}

	private boolean isBankNpc(int id)
	{
		return bankNpcCache.computeIfAbsent(id, this::computeIsBankNpc);
	}

	private boolean computeIsBankNpc(int id)
	{
		NPCComposition comp = client.getNpcDefinition(id);
		if (comp == null)
		{
			return false;
		}

		if (comp.getConfigs() != null)
		{
			NPCComposition transformed = comp.transform();
			if (transformed != null)
			{
				comp = transformed;
			}
		}

		String name = comp.getName();
		if (name == null || name.equalsIgnoreCase("null"))
		{
			return false;
		}

		String[] actions = comp.getActions();
		if (actions != null)
		{
			for (String action : actions)
			{
				if (action != null && action.equalsIgnoreCase("Bank"))
				{
					return true;
				}
			}
		}

		return name.toLowerCase().contains("banker");
	}
}

package com.bankstandingxp;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.Deque;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.ImageUtil;

/**
 * Mimics the vanilla XP drop popup for the fake Bankstanding skill, since
 * the real xp-drop widget only knows about the 23 real in-game skills.
 * Laid out the same way as a real drop: number first, skill icon after.
 */
public class BankstandingXpDropOverlay extends Overlay
{
	private static final long LIFETIME_MS = 3000;
	private static final long FADE_MS = 700;
	private static final int MAX_STACK = 6;
	private static final int BASE_ICON_SIZE = 17;

	private final BankstandingXPConfig config;
	private final Deque<Drop> drops = new ArrayDeque<>();
	private final BufferedImage icon;

	@Inject
	private BankstandingXpDropOverlay(BankstandingXPConfig config)
	{
		this.config = config;
		this.icon = ImageUtil.loadImageResource(getClass(), "bank_icon.png");
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/** Positive amounts are xp gained; negative ones are xp lost (shown red). */
	void addDrop(long amount)
	{
		if (amount == 0)
		{
			return;
		}
		drops.addLast(new Drop(amount, System.currentTimeMillis()));
		while (drops.size() > MAX_STACK)
		{
			drops.removeFirst();
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showXpDrops())
		{
			return null;
		}

		long now = System.currentTimeMillis();
		drops.removeIf(d -> now - d.timestamp > LIFETIME_MS);

		if (drops.isEmpty())
		{
			return null;
		}

		float scale = Math.max(0.25f, config.dropSize() / 100f);
		int iconSize = Math.round(BASE_ICON_SIZE * scale);

		Font baseFont = FontManager.getRunescapeSmallFont();
		Font font = baseFont.deriveFont(baseFont.getSize2D() * scale);
		graphics.setFont(font);
		FontMetrics fm = graphics.getFontMetrics();
		int rowHeight = Math.max(iconSize, fm.getHeight()) + Math.round(3 * scale);

		int maxWidth = 0;
		int y = 0;
		for (Drop drop : drops)
		{
			String text = String.valueOf(drop.amount);
			long age = now - drop.timestamp;
			float alpha = age > LIFETIME_MS - FADE_MS
				? Math.max(0f, 1f - (age - (LIFETIME_MS - FADE_MS)) / (float) FADE_MS)
				: 1f;

			int textWidth = fm.stringWidth(text);
			int textX = 0;
			int textY = y + (rowHeight + fm.getAscent()) / 2 - 2;
			int iconX = textWidth + Math.round(4 * scale);

			graphics.setColor(new Color(0, 0, 0, (int) (200 * alpha)));
			graphics.drawString(text, textX + 1, textY + 1);

			graphics.setColor(drop.amount < 0
				? new Color(255, 70, 70, (int) (255 * alpha))
				: new Color(255, 255, 0, (int) (255 * alpha)));
			graphics.drawString(text, textX, textY);

			Composite original = graphics.getComposite();
			graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
			graphics.drawImage(icon, iconX, y + (rowHeight - iconSize) / 2, iconSize, iconSize, null);
			graphics.setComposite(original);

			maxWidth = Math.max(maxWidth, iconX + iconSize);
			y += rowHeight;
		}

		return new Dimension(maxWidth, y);
	}

	private static final class Drop
	{
		private final long amount;
		private final long timestamp;

		private Drop(long amount, long timestamp)
		{
			this.amount = amount;
			this.timestamp = timestamp;
		}
	}
}

package com.bankstandingxp;

/**
 * Remembers whether the player was in combat with a boss a moment ago. Checking only the exact tick of
 * death misses most boss deaths: fights constantly flip the player's target to a minion, or the player
 * steps away or eats, so "interacting with a boss right now" is often false when they actually die.
 */
final class BossEngagement
{
	/** About 7 seconds of game time. */
	static final int WINDOW_TICKS = 12;

	private int ticksSinceEngaged = Integer.MAX_VALUE;

	/** Call once per game tick. */
	void tick(boolean engagedNow)
	{
		if (engagedNow)
		{
			ticksSinceEngaged = 0;
		}
		else if (ticksSinceEngaged < Integer.MAX_VALUE)
		{
			ticksSinceEngaged++;
		}
	}

	boolean recentlyEngaged()
	{
		return ticksSinceEngaged <= WINDOW_TICKS;
	}

	void reset()
	{
		ticksSinceEngaged = Integer.MAX_VALUE;
	}
}

